def parse_blocks(text: str):
    lines = text.splitlines()
    header = []
    blocks = []
    current = None
    for line in lines:
        match = re.match(r"^(\d+)\.\s+(.*)", line)
        if match:
            if current:
                blocks.append(current)
            current = {
                "num": int(match.group(1)),
                "title": match.group(2).strip(),
                "lines": [],
            }
        elif current:
            current["lines"].append(line)
        else:
            header.append(line)
    if current:
        blocks.append(current)
    return header, blocks


def strip_generated(lines):
    clean = []
    skip = False
    for line in lines:
        if line.strip() == GENERATED_START:
            skip = True
            continue
        if line.strip() in GENERATED_MARKERS:
            skip = True
            continue
        if skip and line.startswith("Источник:"):
            skip = False
            clean.append(line)
            continue
        if not skip:
            clean.append(line)
    return [line for line in clean if line.strip()]


def expand_abbreviations(text: str) -> str:
    for short, full in sorted(ABBREVIATIONS.items(), key=lambda item: -len(item[0])):
        text = re.sub(rf"\b{re.escape(short)}\b", full, text)
    return text


def source_index(lines):
    for index, line in enumerate(lines):
        if line.startswith("Источник:"):
            return index
    return len(lines)


def body_text(lines):
    index = source_index(lines)
    return " ".join(line.strip() for line in lines[:index] if line.strip())


def topic_key(title):
    key = re.split(r"[:.]", title, maxsplit=1)[0]
    key = re.split(r",", key, maxsplit=1)[0]
    return key.strip(" .")


def is_drug_class_question(title: str) -> bool:
    title_lower = title.lower()
    return bool(
        re.search(
            r"механизм действия|классификация нпвс|глюкокортикоид|антагонистов кальция|ингибиторов апф|сердечные гликозиды|антибиотики",
            title_lower,
        )
    )


def definition(block, original):
    override = DEFINITION_OVERRIDES.get(block["num"])
    if override:
        return override
    first_sentence = re.split(r"(?<=[.!?])\s+", original.strip(), maxsplit=1)[0]
    if " - " in first_sentence and len(first_sentence) <= 260:
        return expand_abbreviations(first_sentence)
    if first_sentence and 40 <= len(first_sentence) <= 520:
        return expand_abbreviations(first_sentence)
    key = topic_key(block["title"])
    return f"{key} - тема внутренней медицины, рассматривающая сущность состояния или метода, причины, основные проявления, критерии подтверждения и лечебную тактику."


def clinical_note(block, original):
    title = block["title"]
    if is_drug_class_question(title):
        return None
    return CLINIC_OVERRIDES.get(block["num"])


def diagnosis_note(block, original):
    override = DIAGNOSIS_OVERRIDES.get(block["num"])
    if override:
        return override
    title = block["title"]
    if is_drug_class_question(title) and "диагн" not in title.lower():
        return None
    text = title.lower()
    for pattern, note in SPECIFIC_DIAGNOSIS:
        if re.search(pattern, text):
            return note
    return None


def treatment_note(block, original):
    if block["num"] in TREATMENT_SKIP:
        return None
    override = TREATMENT_OVERRIDES.get(block["num"])
    if override:
        return override
    title = block["title"]
    text = title.lower()
    for pattern, note in SPECIFIC_TREATMENT:
        if re.search(pattern, text):
            return note
    return None


def dispensary_note(title, original):
    if is_drug_class_question(title):
        return None
    text = title.lower()
    for pattern, note in DISPENSARY_PATTERNS:
        if re.search(pattern, text):
            return note
    if "диспансер" in text:
        return "Диспансерное наблюдение определяют по основному диагнозу и осложнениям: после острых неосложненных заболеваний обычно 6-12 месяцев до стойкого выздоровления, при хронических прогрессирующих заболеваниях - длительно или пожизненно; конкретный срок сверяют с локальным приказом."
    return None


def enhance_block(block):
    lines = strip_generated(block["lines"])
    original = body_text(lines)
    generated = [
        GENERATED_START,
        f"Понятие/определение: {definition(block, original)}",
    ]
    clinic = clinical_note(block, original)
    if clinic:
        generated.append(f"Клиника (расширенно): {clinic}")
    diagnosis = diagnosis_note(block, original)
    if diagnosis:
        generated.append(f"Диагностика (признаки и подтверждение): {diagnosis}")
    treatment = treatment_note(block, original)
    if treatment:
        generated.append(
            "Лечение (препараты полностью, типовые взрослые дозы и курсы): "
            + treatment
        )
    dispensary = dispensary_note(block["title"], original)
    if dispensary:
        generated.append(f"Диспансерный учет: {dispensary}")

    index = source_index(lines)
    return lines[:index] + generated + lines[index:]


def render_answers_text(header, blocks):
    output = list(header)
    if output and output[-1].strip():
        output.append("")
    for block in blocks:
        output.append(f"{block['num']}. {block['title']}")
        output.extend(enhance_block(block))
        output.append("")
    return "\n".join(output).rstrip() + "\n"


def linkify_text(raw: str) -> str:
    output = []
    position = 0
    for match in re.finditer(r"https?://[^\s]+", raw):
        output.append(html.escape(raw[position:match.start()]))
        url = match.group(0)
        trailing = ""
        while url and url[-1] in ".,;":
            trailing = url[-1] + trailing
            url = url[:-1]
        escaped_url = html.escape(url, quote=True)
        output.append(
            f'<a href="{escaped_url}" target="_blank" rel="noopener">{html.escape(url)}</a>'
        )
        output.append(html.escape(trailing))
        position = match.end()
    output.append(html.escape(raw[position:]))
    return "".join(output)


