def render_html(header, blocks):
    toc = "\n".join(
        f'        <a class="toc-link" href="#q{block["num"]}">{block["num"]}</a>'
        for block in blocks
    )
    articles = []
    for block in blocks:
        lines = strip_generated(block["lines"])
        enhanced = enhance_block({**block, "lines": lines})
        index = source_index(enhanced)
        body_lines = [line for line in enhanced[:index] if line.strip()]
        source_lines = [line for line in enhanced[index:] if line.strip()]
        data_search = html.escape(
            f"{block['title']} {' '.join(body_lines)} {' '.join(source_lines)}".lower(),
            quote=True,
        )
        body_html = []
        for line in body_lines:
            css_class = ' class="generated"' if line.startswith(GENERATED_START) or re.match(r"^(Понятие/определение|Клиника|Диагностика|Лечение|Диспансерный учет)(?:\s*\([^)]*\))?:", line) else ""
            body_html.append(f"        <p{css_class}>{html.escape(line)}</p>")
        source_text = " ".join(line.replace("Источник:", "", 1).strip() for line in source_lines)
        article = f"""
    <article class="answer-card" id="q{block['num']}" data-search="{data_search}" data-found="yes">
      <div class="card-topline">
        <a class="number-pill" href="#q{block['num']}" aria-label="Вопрос {block['num']}">{block['num']}</a>
        <span class="status found">ответ найден</span>
      </div>
      <h2>{html.escape(block['title'])}</h2>
      <div class="answer-body">
{chr(10).join(body_html)}
      </div>
      <div class="source-block">
        <span>Источник</span>
        <p>{linkify_text(source_text)}</p>
      </div>
    </article>"""
        articles.append(article)

    header_note = html.escape(" ".join(line for line in header if line.strip()))
    return f"""<!doctype html>
<html lang="ru">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Ответы с источниками</title>
  <style>{HTML_STYLE}
  </style>
</head>
<body id="top">
  <div class="page-shell">
    <aside class="sidebar" aria-label="Навигация по вопросам">
      <div class="brand">
        <h1>Ответы</h1>
        <div class="meta">{len(blocks)} вопросов. Добавлены определения, расширенная клиника, диагностические признаки, дозировки и сроки наблюдения.</div>
      </div>
      <a class="back-link" href="index.html">К тестам</a>
      <nav class="toc" aria-label="Номера вопросов">
{toc}
      </nav>
    </aside>
    <main>
      <section class="hero">
        <h1>Ответы с источниками</h1>
        <p>{header_note}</p>
        <p>Дозировки указаны как учебные типовые схемы для взрослых; в реальной практике их сверяют с локальным протоколом, возрастом, беременностью, аллергиями, функцией почек и печени.</p>
        <div class="stats">
          <span class="stat">{len(blocks)} вопросов</span>
          <span class="stat">дата актуальности: 01.06.2026</span>
          <span class="stat">добавлены дозировки и сроки учета</span>
        </div>
      </section>
      <section class="toolbar" aria-label="Поиск">
        <input class="search-input" id="searchInput" type="search" placeholder="Поиск по ответам, препаратам, дозировкам..." autocomplete="off">
        <span class="count-chip" id="resultCount">{len(blocks)} найдено</span>
      </section>
      <div class="answers-list" id="answersList">
{chr(10).join(articles)}
      </div>
      <div class="empty-state" id="emptyState">Ничего не найдено</div>
    </main>
  </div>
  <script>
    const cards = Array.from(document.querySelectorAll('.answer-card'));
    const input = document.getElementById('searchInput');
    const count = document.getElementById('resultCount');
    const empty = document.getElementById('emptyState');

    function applySearch() {{
      const query = input.value.trim().toLowerCase();
      let visible = 0;
      for (const card of cards) {{
        const matched = !query || card.dataset.search.includes(query);
        card.classList.toggle('is-hidden', !matched);
        if (matched) visible += 1;
      }}
      count.textContent = `${{visible}} найдено`;
      empty.classList.toggle('is-visible', visible === 0);
    }}

    input.addEventListener('input', applySearch);
  </script>
</body>
</html>
"""


def main():
    text = ANSWERS_PATH.read_text(encoding="utf-8")
    header, blocks = parse_blocks(text)
    enhanced_text = render_answers_text(header, blocks)
    ANSWERS_PATH.write_text(enhanced_text, encoding="utf-8")

    header, blocks = parse_blocks(enhanced_text)
    HTML_PATH.write_text(render_html(header, blocks), encoding="utf-8")
    print(f"enhanced {len(blocks)} answers")


if __name__ == "__main__":
    main()
